#define main preserved_native_main
#include "../mr-cuda/main.cu"
#undef main
#include <vector>
#include <string>
__global__ void evidence(const uint32_t*b,const uint32_t*n,uint32_t*out,bool eff,int width){int j=blockIdx.x*blockDim.x+threadIdx.x;if(j<100000)for(int c=1;c<=3;c++)out[width*300000+3*j+c-1]=eff?efficient_mr32(b,c,n[j]):straightforward_mr32(b,c,n[j]);}
std::vector<uint32_t> readv(const std::string&name){FILE*f=fopen(name.c_str(),"rb");if(!f)exit(3);fseek(f,0,SEEK_END);size_t size=ftell(f);rewind(f);std::vector<uint32_t>a(size/4);fread(a.data(),4,a.size(),f);fclose(f);return a;}
int main(int argc,char**argv){std::string distribution=argv[1];bool eff=std::string(argv[2])=="efficient";auto ns=readv("study_"+distribution+"_u32.bin"),expected=readv("study_expected_"+distribution+"_u32.bin");uint32_t*b,*n,*codes;int*val;cudaMalloc(&b,12);cudaMalloc(&n,1600000);cudaMalloc(&codes,4800000);cudaMalloc(&val,4);cudaMemcpy(b,bases32,12,cudaMemcpyHostToDevice);cudaMemcpy(n,ns.data(),1600000,cudaMemcpyHostToDevice);
auto launch=[&](int width){if(eff)mr32_eff<<<391,256>>>(b,n+width*100000,val,100000);else mr32_sf<<<391,256>>>(b,n+width*100000,val,100000);};auto eval=[&](){for(int width=0;width<4;width++)evidence<<<391,256>>>(b,n+width*100000,codes,eff,width);};for(int width=0;width<4;width++){cudaMemset(val,0,4);launch(width);if(cudaDeviceSynchronize()!=cudaSuccess)return 4;}eval();if(cudaDeviceSynchronize()!=cudaSuccess)return 5;
bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0;std::vector<uint32_t>out(1200004);bool ok=true;for(int width=0;width<4;width++){for(int rep=0;rep<10;rep++){cudaMemset(val,0,4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();launch(width);auto status=cudaDeviceSynchronize();seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;ok&=status==cudaSuccess;}cudaMemcpy(out.data()+1200000+width,val,4,cudaMemcpyDeviceToHost);}eval();ok&=cudaDeviceSynchronize()==cudaSuccess;cudaMemcpy(out.data(),codes,4800000,cudaMemcpyDeviceToHost);uint64_t error=0;double relative=0;for(size_t i=0;i<out.size();i++){uint64_t diff=out[i]>=expected[i]?uint64_t(out[i])-expected[i]:uint64_t(expected[i])-out[i];error=std::max(error,diff);relative=std::max(relative,double(diff)/std::max(double(expected[i]),1.));}ok&=error==0;allok&=ok;std::vector<uint32_t>got;got.insert(got.end(),bases32,bases32+3);got.insert(got.end(),ns.begin(),ns.end());got.insert(got.end(),out.begin(),out.end());char name[80];snprintf(name,80,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(got.data(),4,got.size(),f);fclose(f);
printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%llu,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),(unsigned long long)error,relative,name,got.size());}return allok?0:1;}
